 * Formatter для итоговой колонки "total"
 */
function budget_cell_formatter_total(frm, periods, value, row, col, data) {
    let lines = "";
    
    if ( data ) {
        let buckets = data.dimension_data || [];
        
        if ( !buckets.length) {
            buckets.push({});
