                ["Project Budget Dimension", "doc", "=", d.doc ], 
                ["Project Budget Dimension", "docname", "=", d.docname ] ]; } ).flat();
                
    frappe.db.get_list("Project Budget", {
        filters: [
            [ "pb_project", "=", project],
            [ "pb_account", "=", account],
        ].concat( dimenstions || [] ),
        fields: ["name"],
        limit: 1
    }).then(result => {
        if (result && result.length > 0) {
            return frappe.db.get_doc("Project Budget", result[0].name);
        } else {
            let new_doc = {
                doctype: "Project Budget",
                pb_project: project,
                pb_account: account,
